mapper.select:
SELECT COUNT(1)
FROM user_address
WHERE user_id = #{userId}

mapper.delete:
DELETE FROM user_address
WHERE id = #{addressId}
  AND user_id = #{userId}

mapper.update:
UPDATE user_address
SET is_default = TRUE,
    updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{addressId}
  AND user_id = #{userId}
